  "signal-state.page.ts": "import { Component, inject } from '@angular/core';\nimport { MatButtonModule } from '@angular/material/button';\nimport { MatCardModule } from '@angular/material/card';\nimport { MatCheckboxModule } from '@angular/material/checkbox';\nimport { MatChipsModule } from '@angular/material/chips';\nimport { MatFormFieldModule } from '@angular/material/form-field';\nimport { MatIconModule } from '@angular/material/icon';\nimport { MatInputModule } from '@angular/material/input';\nimport { DemoPage } from '../../shared/demo-page/demo-page';\nimport { StateInspector } from '../../shared/state-inspector/state-inspector';\nimport { SNIPPETS } from './signal-state.snippets';\nimport { IsolatedTodoWidget, TodoWidget } from './todo-widget';\nimport { TodoFilter, TodoStore } from './todo.store';\n\n/** Video 018 – Lightweight state management with a signal store. */\n@Component({\n  selector: 'app-signal-state-page',\n  imports: [\n    DemoPage,\n    IsolatedTodoWidget,\n    MatButtonModule,\n    MatCardModule,\n    MatCheckboxModule,\n    MatChipsModule,\n    MatFormFieldModule,\n    MatIconModule,\n    MatInputModule,\n    StateInspector,\n    TodoWidget,\n  ],\n  templateUrl: './signal-state.page.html',\n  styleUrl: './signal-state.page.scss',\n})\nexport class SignalStatePage {\n  readonly store = inject(TodoStore);\n  readonly snippets = SNIPPETS;\n  readonly filters: readonly TodoFilter[] = ['all', 'active', 'done'];\n\n  setFilter(value: unknown): void {\n    if (this.filters.includes(value as TodoFilter)) {\n      this.store.setFilter(value as TodoFilter);\n    }\n  }\n}\n",
  "todo-widget.ts": "import { Component, inject, input } from '@angular/core';\nimport { MatButtonModule } from '@angular/material/button';\nimport { MatCheckboxModule } from '@angular/material/checkbox';\nimport { MatIconModule } from '@angular/material/icon';\nimport { TodoStore } from './todo.store';\n\n/** Compact widget – which store instance it gets depends on where it is provided. */\n@Component({\n  selector: 'app-todo-widget',\n  imports: [MatButtonModule, MatCheckboxModule, MatIconModule],\n  template: `\n    <h4>{{ title() }}</h4>\n    <p class=\"demo-hint\">{{ store.remaining() }} open · {{ store.todos().length }} total</p>\n    <ul>\n      @for (todo of store.todos(); track todo.id) {\n        <li>\n          <mat-checkbox [checked]=\"todo.done\" (change)=\"store.toggle(todo.id)\">{{\n            todo.title\n          }}</mat-checkbox>\n        </li>\n      }\n    </ul>\n    <form class=\"add\" (submit)=\"$event.preventDefault(); store.add(input.value); input.value = ''\">\n      <input #input type=\"text\" [attr.aria-label]=\"'New todo for ' + title()\" placeholder=\"Add…\" />\n      <button mat-icon-button type=\"submit\" [attr.aria-label]=\"'Add todo to ' + title()\">\n        <mat-icon>add</mat-icon>\n      </button>\n    </form>\n  `,\n  styles: `\n    :host {\n      display: block;\n      padding: 12px;\n      border-radius: var(--mat-sys-corner-medium);\n      border: 1px solid var(--mat-sys-outline-variant);\n      background: var(--mat-sys-surface);\n    }\n    h4 {\n      margin: 0;\n      font: var(--mat-sys-title-small);\n    }\n    ul {\n      list-style: none;\n      margin: 0;\n      padding: 0;\n    }\n    .add {\n      display: flex;\n      align-items: center;\n    }\n    input {\n      flex: 1;\n      min-width: 0;\n      padding: 6px 8px;\n      border: 1px solid var(--mat-sys-outline);\n      border-radius: var(--mat-sys-corner-small);\n      background: var(--mat-sys-surface);\n      color: var(--mat-sys-on-surface);\n    }\n  `,\n})\nexport class TodoWidget {\n  readonly store = inject(TodoStore);\n  readonly title = input('Widget');\n}\n\n/** Same widget, but with its own store instance: feature state via component providers. */\n@Component({\n  selector: 'app-isolated-todo-widget',\n  imports: [TodoWidget],\n  providers: [TodoStore],\n  template: `<app-todo-widget [title]=\"title()\" />`,\n})\nexport class IsolatedTodoWidget {\n  readonly title = input('Isolated widget');\n}\n",
  "todo.store.ts": "import { Service, computed, signal } from '@angular/core';\n\nexport interface Todo {\n  id: number;\n  title: string;\n  done: boolean;\n}\n\nexport type TodoFilter = 'all' | 'active' | 'done';\n\nexport interface TodoState {\n  todos: Todo[];\n  filter: TodoFilter;\n}\n\nconst INITIAL: TodoState = {\n  todos: [\n    { id: 1, title: 'Watch video 018', done: true },\n    { id: 2, title: 'Write a signal store', done: false },\n  ],\n  filter: 'all',\n};\n\n/** One private signal, a few computed selectors and methods – that's the store. */\n@Service()\nexport class TodoStore {\n  readonly #state = signal<TodoState>(INITIAL);\n  #nextId = 3;\n\n  // Read-only outside: selectors\n  readonly state = this.#state.asReadonly();\n  readonly todos = computed(() => this.#state().todos);\n  readonly filter = computed(() => this.#state().filter);\n  readonly remaining = computed(() => this.todos().filter((t) => !t.done).length);\n  readonly visible = computed(() => {\n    const { todos, filter } = this.#state();\n    return filter === 'all' ? todos : todos.filter((t) => t.done === (filter === 'done'));\n  });\n\n  // Updates as methods\n  add(title: string): void {\n    const trimmed = title.trim();\n    if (!trimmed) return;\n    const todo: Todo = { id: this.#nextId++, title: trimmed, done: false };\n    this.#state.update((s) => ({ ...s, todos: [...s.todos, todo] }));\n  }\n\n  toggle(id: number): void {\n    this.#state.update((s) => ({\n      ...s,\n      todos: s.todos.map((t) => (t.id === id ? { ...t, done: !t.done } : t)),\n    }));\n  }\n\n  remove(id: number): void {\n    this.#state.update((s) => ({ ...s, todos: s.todos.filter((t) => t.id !== id) }));\n  }\n\n  clearCompleted(): void {\n    this.#state.update((s) => ({ ...s, todos: s.todos.filter((t) => !t.done) }));\n  }\n\n  setFilter(filter: TodoFilter): void {\n    this.#state.update((s) => ({ ...s, filter }));\n  }\n\n  reset(): void {\n    this.#state.set(INITIAL);\n  }\n}\n",
